use vstd::prelude::*;

verus! {
    /// Splits the input vector `a` into two halves:
    /// the first floor(len/2) elements go into `first`,
    /// the rest go into `second`.
    fn array_split(mut a: Vec<i32>) -> (first: Vec<i32>, second: Vec<i32>)
        ensures
            // Let mid be the split point in the mathematical sequence `a@`
            let mid: nat = a@.len() / 2;
            // Lengths agree
            first.len() == mid,
            second.len() == a@.len() - mid,
            // Contents agree with slicing the original
            first@ == a@.slice(0, mid),
            second@ == a@.slice(mid, a@.len()),
    {
        let mid = a.len() / 2;
        let second = a.split_off(mid);
        let first = a;
        (first, second)
    }
}

